var React = require('react');

var ReactCSSTransitionGroup = require('react-addons-css-transition-group');
var PropTypes = require('prop-types');

class BoosterSelection extends React.Component {

    constructor(props) {
        super(props);
        this.state = {
            sets : [],
            firstCol: [],
            secondCol: [],
            thirdCol: []
        }

        this.fillColumns = this.fillColumns.bind(this);
        this.getSets = this.getSets.bind(this);
        this.handleClick = this.handleClick.bind(this);
    }

    // Handles selecting a booster
    handleClick(e, code) {
        this.props.toggleSet(code);
        this.props.toggleMode();
    }

    // Fetches a full set list from magicthegathering.io
    getSets() {

        fetch('https://api.magicthegathering.io/v1/sets/').then(function(response) {

            return response.json();

        }).then(function(json) {

            var arr = [];
            for (var i = 0; i < json.sets.length; i++) {

                // Only renders 'expansion', 'core', 'masters' and 'reprint' sets
                if (json.sets[i].type === "expansion" || json.sets[i].type === "core" ||
                        json.sets[i].type === "masters" || json.sets[i].type === "reprint") {

                    // Skips out Aether Revolt because of an upstream issue
                    if (json.sets[i].code === "AER") {continue;}

                    // Adds a dateObj to sort the sets
                    var t = new Date(json.sets[i].releaseDate);
                    json.sets[i].dateObj = t.getTime();
                    arr.push(json.sets[i]);
                }

            }

            // Sorts the sets by chronological order
            arr.sort(function (a, b) {
                return b.dateObj - a.dateObj;
              });
            this.fillColumns(arr);

        }.bind(this))}

    // Takes an array of set data, and fills the three columns
    // to be displayed on the view
    fillColumns(arr) {

        arr = arr.slice(0, 24);
        var ticker = 1;

        for(var i = 0; i < arr.length; i++) {
            if (ticker === 1) {

                var c = this.state.firstCol;
                c.push(arr[i]);
                this.setState({firstCol : c});
                ticker++;

            } else if (ticker === 2) {

                var c = this.state.secondCol;
                c.push(arr[i]);
                this.setState({secondCol : c});
                ticker++;

            } else {

                var c = this.state.thirdCol;
                c.push(arr[i]);
                this.setState({thirdCol : c});
                ticker = 1;

            }
        }
    }

    componentWillMount() {
        this.getSets();
    }

    render() {
        return (

            <ReactCSSTransitionGroup
            transitionName="backdrop"
            transitionAppear={true}
            transitionLeave={true}
            transitionAppearTimeout={1000}
            transitionLeaveTimeout={1000}
            >

                <div className="row">

                    <div className="col-xs-4">
                        {this.state.firstCol.map(function(item, i) {
                            return (
                            <div key={i}
                                className="booster"
                                onClick={(e) => this.handleClick(e, item.code)}>
                                <img alt={item.name} src={"/img/"+item.code.toLowerCase()+".JPG"} style={{width: "100%"}}/>
                            </div>);
                        }, this)}
                    </div>

                    <div className="col-xs-4">
                        {this.state.secondCol.map(function(item, i) {
                            return (
                                <div key={i}
                                    className="booster"
                                    onClick={(e) => this.handleClick(e, item.code)}>
                                    <img alt={item.name} src={"/img/"+item.code.toLowerCase()+".JPG"} style={{width: "100%"}}/>
                            </div>);
                        }, this)}
                    </div>

                    <div className="col-xs-4">
                        {this.state.thirdCol.map(function(item, i) {
                            return (
                                <div key={i}
                                    className="booster"
                                    onClick={(e) => this.handleClick(e, item.code)}>
                                    <img alt={item.name} src={"/img/"+item.code.toLowerCase()+".JPG"} style={{width: "100%"}}/>
                            </div>);
                        }, this)}
                    </div>

                </div>

            </ReactCSSTransitionGroup>

        )
    }
}

BoosterSelection.propTypes = {

    toggleMode: PropTypes.func,
    toggleSet: PropTypes.func

}

module.exports = BoosterSelection;

var React = require('react');

var MainArea = require('./mainarea');
var Loader = require('./loader.js');
var Title = require('../title.js');
var PropTypes = require('prop-types');

var ReactCSSTransitionGroup = require('react-addons-css-transition-group');

class Crack extends React.Component {

    constructor(props) {
      super(props);
      this.state = {
        boosterCount: 0,
        boostersOpened: 1,
        imagesLoaded: 0,
        loaded: false,
        loadCard : "",
        loadPercent : 0,
        booster: {
          cards: []
        },
        mainCard: {}

      };

      this.nextCard = this.nextCard.bind(this);
      this.generateBooster = this.generateBooster.bind(this);
      this.nextBooster = this.nextBooster.bind(this);
      this.handleImageLoaded = this.handleImageLoaded.bind(this);
    }

    // Handles next Card
    nextCard() {

        var c = this.state.boosterCount - 1;

        if (c > 0) {
            this.setState({boosterCount: c});
            this.setState({
                mainCard: this.state.booster.cards[c]
            });

        } else if (c === 0) {
            this.setState({boosterCount: c});
            this.setState({
                mainCard: this.state.booster.cards[c]
            });

        } else if (c === -1) {
          this.props.toggle();
        }

    }

    // Detects if image loaded in preloader, updates state
    handleImageLoaded(response) {

      var c = this.state.imagesLoaded + 1;
      var l = this.state.booster.cards.length;
      var percent = Math.ceil(( c / l ) * 100);

      var loaded = false;
      if (percent === 100) {
        loaded = true;
        percent = 0;
        c = 0;
      };

      this.setState({
        loaded: loaded,
        imagesLoaded: c,
        loadPercent: percent
      });

    }

    // Next booster
    nextBooster() {

      this.setState({mainCard: {}, loaded: false});
      this.generateBooster(this.props.setCode);
      this.props.updateBoosters();

    }

    // Fetches a booster JSON object from the API, based on a setCode
    generateBooster(set) {

        fetch('https://api.magicthegathering.io/v1/sets/'+set+'/booster')
          .then(function(response) {
            return response.json();
          }).then(function(json) {

            this.setState({booster: json
            });
            this.setState({boosterCount: this.state.booster.cards.length - 1});
            this.setState({
                mainCard: this.state.booster.cards[this.state.boosterCount]
            });

          }.bind(this));

    }

    componentWillMount() {
        this.generateBooster(this.props.setCode);
    }

    render() {

      return (

        <div className="container-fluid hide-overflow">

          <div className="row">

            <div className="col-md-12 background light">

              <Title/>

              {/* Image Preloader
                * A row of invisible images that report their load status
                */}
              {this.state.booster.cards.slice(0).reverse().map(function(item, i) {
                return (
                  <img key={i}
                  src={item.imageUrl}
                  className="card__prep"
                  onError={this.handleImageLoaded}
                  onLoad={this.handleImageLoaded}/>
                )
              }.bind(this))} 

              <ReactCSSTransitionGroup
              transitionName="backdrop"
              transitionAppear={true}
              transitionEnter={true}
              transitionLeave={true}
              transitionAppearTimeout={1000}
              transitionLeaveTimeout={1000}
              >
                {// Note ternary expression
                // If not loaded, display loader. If loaded, display MainArea
                !this.state.loaded
                ?
                  <Loader key={this.state.boostersOpened} loadPercent={this.state.loadPercent}/>
                :
                  <MainArea card={this.state.mainCard}
                  next={this.nextCard}
                  goodClickHandler={this.props.goodClickHandler}
                  badClickHandler={this.props.badClickHandler}
                  boosterCount={this.state.boosterCount}
                  toggle={this.props.toggle}/> 
                }

              </ReactCSSTransitionGroup>

            </div>
          </div>
        </div>
      )
    }
}

Crack.propTypes = {

  toggle: PropTypes.func,
  badClickHandler: PropTypes.func,
  goodClickHandler: PropTypes.func,
  setCode: PropTypes.string,
  updateBoosters: PropTypes.func,

}

module.exports = Crack;

var React = require('react');

var Card = require('./card.js');
var ReactCSSTransitionGroup = require('react-addons-css-transition-group');
var ReactTouchEvents = require("react-touch-events");
var PropTypes = require('prop-types');

class MainArea extends React.Component {

    constructor(props) {
      super(props);

      this.state = {
        lastClick: "good"
      }

      this.handleGoodClick = this.handleGoodClick.bind(this);
      this.handleBadClick = this.handleBadClick.bind(this);
      this.handleSwipe = this.handleSwipe.bind(this);

    }

    // Passes the badclick to the parent
    handleBadClick() {

      this.props.badClickHandler(this.props.card);
      this.setState({lastClick: "bad"});
      this.props.next();

    }

    // Passes the goodclick to the parent
    handleGoodClick() {

      this.props.goodClickHandler(this.props.card);
      this.setState({lastClick: "good"});
      this.props.next();

    }

    // Handles a swipe passed to it from ReactTouchEvents
    handleSwipe (direction) {

      switch (direction) {
          case "left":
          this.handleBadClick();
          break;

          case "bottom":
          this.handleBadClick();
          break;

          case "right":
          this.handleGoodClick();
          break;

          case "top":
          this.handleGoodClick();
          break;
      }
    }

    render() {
      return (
        <div className="container-fluid hide-overflow">

          <ReactTouchEvents
              onSwipe={this.handleSwipe}
              >

            <div className="row row-eq-height">

              <div className="col-xs-2 main-area__button__container">
                <button className="main-area__button"
                  onClick={this.handleBadClick}>
                  <i className="fa fa-thumbs-down" aria-hidden="true"></i>
                </button>
              </div>

              <div className="col-xs-8 card__container">
                <ReactCSSTransitionGroup
                  transitionEnter={true}
                  transitionLeave={true}
                  transitionName={this.state.lastClick === "bad"
                  ?
                  "bad-card"
                  :
                  "good-card"}>
                    <Card card={this.props.card} key={this.props.boosterCount}/>
                </ReactCSSTransitionGroup>
              </div>

          <div className="col-xs-2 main-area__button__container">
            <button className="main-area__button"
                onClick={this.handleGoodClick}>
              <i className="fa fa-thumbs-up" aria-hidden="true"></i>
            </button>
          </div>

          </div>
          </ReactTouchEvents>

        <div className="row">

          <ReactCSSTransitionGroup
                  transitionEnter={true}
                  transitionLeave={true}
                  transitionName="fade"> 

            <div key={this.props.card.name} className="col-xs-12 main-area__descbox">
              <h3 className="fadeInLeft">{this.props.card.name} ({this.props.card.rarity})</h3>
              <h4 className="fadeInLeft">{this.props.card.type}</h4>
              <p className="fadeInLeft hidden-sm hidden-xs">{this.props.card.text}</p>
            </div>

          </ReactCSSTransitionGroup>

        </div>
      </div>
        );
    }
  }

MainArea.propTypes = {

  card: PropTypes.object,
  boosterCount: PropTypes.int,
  next: PropTypes.func,
  badClickHandler: PropTypes.func,
  goodClickHandler: PropTypes.func
}

module.exports = MainArea;
